#!/usr/bin/env bash
# Builds the app generated by convert.sh without an Apple developer account.
#
#   safari/xcode/build-app.sh [project-dir] [macos|ios-simulator] [derived-data-dir]
#
# macos:         Release build, ad-hoc signed (Safari needs "Allow unsigned
#                extensions" to load it).
# ios-simulator: unsigned build for the iOS simulator (to check it compiles;
#                installing on a device needs signing in Xcode).
set -euo pipefail

PROJECT_DIR="${1:-build/safari/xcode}"
PLATFORM="${2:-macos}"
DERIVED="${3:-build/safari/dd}"

PROJECT="$(find "$PROJECT_DIR" -maxdepth 3 -name '*.xcodeproj' | head -1)"
if [ -z "$PROJECT" ]; then
  echo "error: no .xcodeproj under $PROJECT_DIR, run safari/xcode/convert.sh first" >&2
  exit 1
fi

pick_scheme() {
  xcodebuild -list -json -project "$PROJECT" | python3 -c '
import json, sys
schemes = json.load(sys.stdin)["project"]["schemes"]
want = sys.argv[1]
match = [s for s in schemes if want in s]
print(match[0] if match else (schemes[0] if len(schemes) == 1 else ""))
' "$1"
}

case "$PLATFORM" in
  macos)
    SCHEME="$(pick_scheme '(macOS)')"
    set -x
    xcodebuild -quiet -project "$PROJECT" -scheme "$SCHEME" -configuration Release \
      -destination 'generic/platform=macOS' -derivedDataPath "$DERIVED" \
      CODE_SIGN_IDENTITY=- CODE_SIGN_STYLE=Manual DEVELOPMENT_TEAM= PROVISIONING_PROFILE_SPECIFIER= \
      build
    ;;
  ios-simulator)
    SCHEME="$(pick_scheme '(iOS)')"
    set -x
    xcodebuild -quiet -project "$PROJECT" -scheme "$SCHEME" -configuration Release \
      -destination 'generic/platform=iOS Simulator' -derivedDataPath "$DERIVED" \
      CODE_SIGNING_ALLOWED=NO \
      build
    ;;
  *)
    echo "error: unknown platform $PLATFORM (use macos or ios-simulator)" >&2
    exit 1
    ;;
esac
